package com.locallaunch.service;
import com.locallaunch.dto.RatingRequest; import com.locallaunch.entity.CustomerRating; import com.locallaunch.entity.Product; import com.locallaunch.exception.ResourceNotFoundException; import com.locallaunch.repository.CustomerRatingRepository; import com.locallaunch.repository.ProductRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class RatingService { private final CustomerRatingRepository ratingRepo; private final ProductRepository productRepo; public RatingService(CustomerRatingRepository r,ProductRepository p){ratingRepo=r;productRepo=p;} public CustomerRating add(Long productId,RatingRequest req){ Product p=productRepo.findById(productId).orElseThrow(()->new ResourceNotFoundException("Product not found")); CustomerRating r=new CustomerRating(); r.setCustomerName(req.getCustomerName()); r.setRating(req.getRating()); r.setComment(req.getComment()); r.setProduct(p); return ratingRepo.save(r);} public List<CustomerRating> get(Long productId){return ratingRepo.findByProductId(productId);} public double average(Long productId){List<CustomerRating> list=get(productId); return list.stream().mapToInt(CustomerRating::getRating).average().orElse(0);} }
